changeSet.sql:

UPDATE m_product_loan
    SET "name" = CONCAT("name", ' -- Disabled')
        , close_date = '2020-12-10'
WHERE LOWER("name") LIKE '%crédito rotativo%'
        or LOWER("name") LIKE '%credito rotativo%'
;

    UPDATE m_product_loan
        SET short_name = '*004'
    WHERE short_name = 'ROTA';

    UPDATE m_product_loan
        SET short_name = '*005'
    WHERE short_name = 'ROTS';

    UPDATE m_product_loan
        SET short_name = '*006'
    WHERE short_name = 'ROTD';


